import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.vLhlLNVn.js";const p=JSON.parse('{"title":"核心能力与使用场景","description":"","frontmatter":{},"headers":[],"relativePath":"guide/capabilities.md","filePath":"guide/capabilities.md"}'),r={name:"guide/capabilities.md"};function c(i,e,n,l,s,h){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="核心能力与使用场景" tabindex="-1">核心能力与使用场景 <a class="header-anchor" href="#核心能力与使用场景" aria-label="Permalink to &quot;核心能力与使用场景&quot;">​</a></h1><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th><th>关键 API</th></tr></thead><tbody><tr><td>可视化设计器</td><td>隔离 iframe 视图，页面、元素、参考线与撤销历史完整可用</td><td><code>studio.mount()</code>、<code>&lt;PrintDesigner&gt;</code></td></tr><tr><td>八种内置元素</td><td>文本、矩形、圆形、线条、图片、条形码、二维码、表格</td><td><code>elements.add({ type })</code></td></tr><tr><td>数据绑定</td><td>表达式 <span><code>{{ 路径 | 格式化 }}</code></span> + 结构化绑定 + 文档变量</td><td><code>dataSource.upsert()</code></td></tr><tr><td>循环与批量</td><td>标签平铺、每条一页、表格跨页与补空行</td><td><code>repeatGroup.create()</code></td></tr><tr><td>预览与打印</td><td>带数据预览、浏览器打印、嵌入容器、独立完整打印预览</td><td><code>preview()</code> / <code>print()</code></td></tr><tr><td>导出</td><td>独立 HTML、PDF Blob（字体自动收集、旋转元素光栅化）</td><td><code>toHTML()</code> / <code>toPDF()</code></td></tr><tr><td>注册表扩展</td><td>自定义元素 / 解析器 / 插件 / 命令</td><td><code>defineElement()</code>、<code>definePlugin()</code></td></tr><tr><td>事件与状态</td><td>全域事件目录 + 状态快照订阅</td><td><code>events.on()</code>、<code>state.subscribe()</code></td></tr></tbody></table><h2 id="典型使用场景" tabindex="-1">典型使用场景 <a class="header-anchor" href="#典型使用场景" aria-label="Permalink to &quot;典型使用场景&quot;">​</a></h2><h3 id="_1-saas-单据打印" tabindex="-1">1. SaaS 单据打印 <a class="header-anchor" href="#_1-saas-单据打印" aria-label="Permalink to &quot;1. SaaS 单据打印&quot;">​</a></h3><p>在 Web 应用中嵌入设计器，运营人员维护发货单 / 发票模板；系统保存模板 JSON，打印时注入订单数据调用 <code>print()</code> 或 <code>toPDF()</code>。</p><h3 id="_2-标签批量打印" tabindex="-1">2. 标签批量打印 <a class="header-anchor" href="#_2-标签批量打印" aria-label="Permalink to &quot;2. 标签批量打印&quot;">​</a></h3><p>商品标签、货架标签、资产标签：用循环区块（<code>repeatGroup</code>，<code>direction: &#39;grid&#39;</code>）按 3 列 × N 行平铺，超页自动分页；配合 80mm / 58mm 热敏纸预设。</p><h3 id="_3-报表导出" tabindex="-1">3. 报表导出 <a class="header-anchor" href="#_3-报表导出" aria-label="Permalink to &quot;3. 报表导出&quot;">​</a></h3><p>多页报表：表格跨页续排（<code>pagination.crossPage</code>）+ 每页小计 / 全量合计（<code>summary</code>）+ 页码（<code>$document.pageNumber/pageCount</code>），一键导出 PDF。</p><h3 id="_4-纯输出服务" tabindex="-1">4. 纯输出服务 <a class="header-anchor" href="#_4-纯输出服务" aria-label="Permalink to &quot;4. 纯输出服务&quot;">​</a></h3><p>模板由设计器团队维护、业务系统只做输出：<code>createPrintRenderer()</code> 接收模板 JSON + 业务数据，生成 HTML / PDF / 预览 / 打印，不加载任何编辑能力。</p><h3 id="_5-二维码-条形码批量" tabindex="-1">5. 二维码 / 条形码批量 <a class="header-anchor" href="#_5-二维码-条形码批量" aria-label="Permalink to &quot;5. 二维码 / 条形码批量&quot;">​</a></h3><p>出入库、溯源场景：循环区块内放 barcode / qrcode 元素，按数据批量生成码图并打印或导出。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><ul><li>模板渲染依赖浏览器环境，<strong>不支持 Node SSR</strong>；服务端输出需以无头浏览器等宿主承载。</li><li>输出格式为 HTML / PDF / 模板 JSON，无位图导出；各输出入口的返回值与行为见<a href="./../reference/output.html">预览 / 打印 / 导出</a>。</li><li>浏览器打印依赖用户在打印对话框中确认；「静默打印」需宿主环境另行封装。</li></ul>',16)])])}const b=t(r,[["render",c]]);export{p as __pageData,b as default};
